parameters.jsCode:
const res = $input.first().json;
const body = res.body ?? {};

if (res.statusCode !== 200) {
  return [{ json: { ok: false, status: res.statusCode, error: body.error ?? body } }];
}

let parsed;
try {
  parsed = JSON.parse(body.message?.content ?? '');
} catch (e) {
  return [{ json: { ok: false, error: 'Model did not return valid JSON', raw: body.message?.content } }];
}

return [{ json: {
  ok: String(parsed.reply).toLowerCase().includes('pong'),
  reply: parsed.reply,
  model: body.model,
  seconds: Math.round((body.total_duration ?? 0) / 1e8) / 10,
} }];
